#!/usr/bin/env python3
"""Quick estimate of the search space size."""
import itertools
import time

# Replicate map setup and precomputation quickly

_neighbor_cache = {}
def get_neighbors(x, y):
    key = (x, y)
    if key not in _neighbor_cache:
        if y % 2 == 0:
            _neighbor_cache[key] = [(x+1,y),(x,y-1),(x-1,y-1),(x-1,y),(x-1,y+1),(x,y+1)]
        else:
            _neighbor_cache[key] = [(x+1,y),(x+1,y-1),(x,y-1),(x-1,y),(x,y+1),(x+1,y+1)]
    return _neighbor_cache[key]

def offset_to_cube(col, row):
    cx = col - (row - (row & 1)) // 2
    cz = row
    cy = -cx - cz
    return cx, cy, cz

def hex_distance(x1, y1, x2, y2):
    cx1, cy1, cz1 = offset_to_cube(x1, y1)
    cx2, cy2, cz2 = offset_to_cube(x2, y2)
    return (abs(cx1-cx2) + abs(cy1-cy2) + abs(cz1-cz2)) // 2

tiles = {}
def add_tile(x, y, terrain, feat=None, rivers=None):
    tiles[(x,y)] = {'terrain': terrain, 'feature': feat, 'rivers': rivers or {}}

add_tile(22,11,'TERRAIN_GRASS_MOUNTAIN')
add_tile(23,11,'TERRAIN_GRASS',feat='FEATURE_FOREST')
add_tile(24,11,'TERRAIN_GRASS')
