add_tile(26,12,'TERRAIN_GRASS')
add_tile(20,13,'TERRAIN_GRASS',feat='FEATURE_JUNGLE')
add_tile(21,13,'TERRAIN_GRASS',feat='FEATURE_GEOTHERMAL_FISSURE',rivers={'W':1,'NW':1})
add_tile(22,13,'TERRAIN_GRASS')
add_tile(23,13,'TERRAIN_GRASS',feat='FEATURE_FOREST')
add_tile(24,13,'TERRAIN_GRASS')
add_tile(25,13,'TERRAIN_GRASS')
add_tile(26,13,'TERRAIN_GRASS')
add_tile(20,14,'TERRAIN_COAST',feat='FEATURE_REEF')
add_tile(21,14,'TERRAIN_GRASS')
add_tile(22,14,'TERRAIN_GRASS',rivers={'W':1,'NW':1})
add_tile(23,14,'TERRAIN_PLAINS',feat='FEATURE_FLOODPLAINS_PLAINS',rivers={'W':1})
add_tile(24,14,'TERRAIN_GRASS',rivers={'NE':1})
add_tile(25,14,'TERRAIN_GRASS')
add_tile(26,14,'TERRAIN_GRASS')
add_tile(27,14,'TERRAIN_GRASS')
add_tile(20,15,'TERRAIN_GRASS',feat='FEATURE_JUNGLE')
add_tile(21,15,'TERRAIN_GRASS_MOUNTAIN')
add_tile(22,15,'TERRAIN_GRASS',rivers={'NW':1})
add_tile(23,15,'TERRAIN_PLAINS',feat='FEATURE_FLOODPLAINS_PLAINS',rivers={'W':1,'NW':1})
add_tile(24,15,'TERRAIN_GRASS')
add_tile(25,15,'TERRAIN_GRASS')
add_tile(26,15,'TERRAIN_GRASS')
add_tile(22,16,'TERRAIN_GRASS')
add_tile(23,16,'TERRAIN_PLAINS',feat='FEATURE_FLOODPLAINS_PLAINS',rivers={'W':1})
add_tile(24,16,'TERRAIN_GRASS',rivers={'NE':1})
add_tile(25,16,'TERRAIN_GRASS')
add_tile(26,16,'TERRAIN_GRASS')
add_tile(22,17,'TERRAIN_PLAINS',feat='FEATURE_FLOODPLAINS_PLAINS',rivers={'W':1})
add_tile(23,17,'TERRAIN_GRASS',rivers={'NE':1})
add_tile(24,17,'TERRAIN_GRASS')
add_tile(25,17,'TERRAIN_GRASS')

for pos in [(21,11),(20,12),(19,13),(27,12),(28,14),(27,15),(27,16),(21,16),
            (20,16),(22,18),(23,18),(24,18),(25,18),(26,18),(26,17),(21,17),
            (19,15),(26,10),(25,10),(24,10),(23,10),(22,10)]:
    if pos not in tiles:
        add_tile(pos[0],pos[1],'TERRAIN_COAST')

def is_mountain(pos):
    t = tiles.get(pos)
    return t is not None and 'MOUNTAIN' in t['terrain']

def is_coast(pos):
    t = tiles.get(pos)
    return t is not None and t['terrain'] == 'TERRAIN_COAST'

def is_land(pos):
    t = tiles.get(pos)
    return t is not None and t['terrain'] != 'TERRAIN_COAST'

def feat(pos):
    t = tiles.get(pos)
    return t['feature'] if t else None

def is_floodplains(pos):
    f = feat(pos)
    return f is not None and 'FLOODPLAINS' in f

# River computation
def compute_rivers():
    river_set = set()
    edge_count = {}
    all_edges = set()
    flag_to_dir = {'W': 3, 'NW': 2, 'NE': 1}
    for pos, tile in tiles.items():
        if not tile['rivers']:
            continue
        neighbors = get_neighbors(pos[0], pos[1])
        for flag, val in tile['rivers'].items():
            if val == 1:
                d = flag_to_dir[flag]
                neighbor = neighbors[d]
                edge = (min(pos, neighbor), max(pos, neighbor))
                all_edges.add(edge)
    for p1, p2 in all_edges:
        river_set.add(p1)
        river_set.add(p2)
        edge_count[p1] = edge_count.get(p1, 0) + 1
        edge_count[p2] = edge_count.get(p2, 0) + 1
    return river_set, edge_count

RIVER_TILES, RIVER_EDGE_COUNT = compute_rivers()

ADJ = {}
ADJ_SET = {}
for pos in tiles:
    ADJ[pos] = [n for n in get_neighbors(pos[0], pos[1]) if n in tiles]
    ADJ_SET[pos] = set(ADJ[pos])

def on_river(pos):
    return pos in RIVER_TILES

def river_edges(pos):
    return RIVER_EDGE_COUNT.get(pos, 0)

SPECIALTY = ['CAMPUS','HOLY_SITE','THEATER_SQUARE','COMMERCIAL_HUB',
             'HARBOR','INDUSTRIAL_ZONE','ENTERTAINMENT_COMPLEX',
             'ENCAMPMENT','PRESERVE']

def valid_positions_for(dtype, cc):
    result = []
    for pos, tile in tiles.items():
        if pos == cc:
            continue
        if hex_distance(pos[0], pos[1], cc[0], cc[1]) > 3:
            continue
        if is_mountain(pos):
            continue
        if feat(pos) == 'FEATURE_GEOTHERMAL_FISSURE':
            continue
        if dtype == 'HARBOR':
            if not is_coast(pos):
                continue
            if not any(is_land(n) for n in ADJ[pos]):
                continue
        else:
            if is_coast(pos):
                continue
        if dtype == 'AQUEDUCT':
            if cc not in ADJ_SET[pos]:
                continue
            has_fw = any(is_mountain(n) for n in ADJ[pos]) or on_river(pos)
            if not has_fw:
                continue
        if dtype == 'DAM':
            if not is_floodplains(pos):
                continue
            if river_edges(pos) < 2:
                continue
        if dtype == 'ENCAMPMENT' and cc in ADJ_SET[pos]:
            continue
        if dtype == 'PRESERVE' and cc in ADJ_SET[pos]:
            continue
        result.append(pos)
    return result

valid_ccs = sorted([p for p in tiles if is_land(p) and not is_mountain(p)])
print(f"Valid city centers: {len(valid_ccs)}")

total_combos = 0
total_assignments = 0
max_product = 0
worst_combo_info = None

for cc in valid_ccs:
    vp = {}
    for dtype in SPECIALTY + ['AQUEDUCT', 'DAM']:
        positions = valid_positions_for(dtype, cc)
        if positions:
            vp[dtype] = positions

    for combo in itertools.combinations(SPECIALTY, 3):
        if any(d not in vp for d in combo):
            continue

        ns_options = [()]
        if 'AQUEDUCT' in vp:
            ns_options.append(('AQUEDUCT',))
        if 'DAM' in vp:
            ns_options.append(('DAM',))
        if 'AQUEDUCT' in vp and 'DAM' in vp:
            ns_options.append(('AQUEDUCT', 'DAM'))

        for ns in ns_options:
            all_types = list(combo) + list(ns)
            if any(d not in vp for d in all_types):
                continue
            total_combos += 1
            product = 1
            for d in all_types:
                product *= len(vp[d])
            total_assignments += product
            if product > max_product:
                max_product = product
                worst_combo_info = (cc, all_types, {d: len(vp[d]) for d in all_types})

print(f"Total district type combos: {total_combos}")
print(f"Total assignment permutations (upper bound): {total_assignments}")
print(f"Max single combo product: {max_product}")
if worst_combo_info:
    cc, types, sizes = worst_combo_info
    print(f"Worst case: CC={cc}, types={types}, sizes={sizes}")

# Show per-CC stats
print("\nPer-CC stats:")
for cc in valid_ccs:
    vp = {}
    for dtype in SPECIALTY + ['AQUEDUCT', 'DAM']:
        positions = valid_positions_for(dtype, cc)
        if positions:
            vp[dtype] = positions
    sizes = {d: len(vp[d]) for d in vp}
    print(f"  CC={cc}: {sizes}")

